<?php
$page_title='In và xuất phương án TKB';
require_once __DIR__.'/includes/functions.php';
require_once __DIR__.'/includes/timetable_store.php';
require_once dirname(__DIR__).'/includes/timetable_builder.php';
$user=cds_user();if(!$user){header('Location: /login.php?next='.urlencode($_SERVER['REQUEST_URI']??''));exit;}
$canManage=(($user['role']??'')==='admin')||cds_can_feature('cm.nhaplieu','edit');if(!$canManage){http_response_code(403);exit('Bạn chưa có quyền in phương án TKB.');}
$data=ttb_data();$plan=ttb_plan($data,(string)($data['active_plan']??''));$assignments=ttb_assignments();$classes=array_values(array_unique(array_column($assignments,'class')));sort($classes,SORT_NATURAL|SORT_FLAG_CASE);$teachers=array_values(array_unique(array_column($assignments,'teacher')));natcasesort($teachers);$mode=(string)($_GET['mode']??'class');if(!in_array($mode,['class','teacher','school'],true))$mode='class';$class=(string)($_GET['class']??($classes[0]??''));$teacher=(string)($_GET['teacher']??($teachers?reset($teachers):''));
$entries=(array)($plan['entries']??[]);$filtered=array_values(array_filter($entries,function($e)use($mode,$class,$teacher){return$mode==='school'||($mode==='teacher'&&($e['teacher']??'')===$teacher)||($mode==='class'&&in_array($class,(array)($e['classes']??[]),true));}));
if(($_GET['download']??'')==='excel'){header('Content-Type: application/vnd.ms-excel; charset=UTF-8');header('Content-Disposition: attachment; filename="phuong-an-tkb-'.date('Ymd-His').'.xls"');echo"\xEF\xBB\xBF";echo'<table border="1"><tr><th>Thứ</th><th>Buổi</th><th>Tiết</th><th>Lớp</th><th>Môn</th><th>Giáo viên</th></tr>';foreach($filtered as$e)echo'<tr><td>'.e($e['day']).'</td><td>'.e($e['session']).'</td><td>'.e($e['period']).'</td><td>'.e(implode(' + ',$e['classes'])).'</td><td>'.e($e['subject']).'</td><td>'.e($e['teacher']).'</td></tr>';echo'</table>';exit;}
function tkbp_matrix(array$entries,array$settings,string$title):void{$grid=[];foreach($entries as$e)$grid[$e['session']][$e['period']][$e['day']][]=$e;echo'<h5 class="print-title">'.e($title).'</h5><table class="print-grid"><thead><tr><th>Buổi</th><th>Tiết</th>';foreach($settings['days']as$d)echo'<th>Thứ '.e($d).'</th>';echo'</tr></thead><tbody>';foreach(['Sáng'=>(int)$settings['morning_periods'],'Chiều'=>(int)$settings['afternoon_periods']]as$session=>$max)for($p=1;$p<=$max;$p++){echo'<tr>';if($p===1)echo'<th rowspan="'.$max.'">'.e($session).'</th>';echo'<th>'.$p.'</th>';foreach($settings['days']as$d){echo'<td>';foreach((array)($grid[$session][$p][$d]??[])as$e)echo'<strong>'.e($e['subject']).'</strong><small>'.e(implode(' + ',$e['classes'])).' · '.e($e['teacher']).'</small>';echo'</td>';}echo'</tr>';}echo'</tbody></table>';}
require_once __DIR__.'/includes/header.php';
?>
