<?php if(!$plan):?><div class="alert alert-warning">Chưa có phương án đang làm việc.</div><?php else:?><form class="print-toolbar p-3 mb-3 d-flex gap-2 flex-wrap align-items-end"><div><label class="form-label">Phạm vi</label><select class="form-select" name="mode" onchange="this.form.submit()"><option value="class" <?=$mode==='class'?'selected':''?>>Theo lớp</option><option value="teacher" <?=$mode==='teacher'?'selected':''?>>Theo giáo viên</option><option value="school" <?=$mode==='school'?'selected':''?>>Toàn trường</option></select></div><?php if($mode==='class'):?><div><label class="form-label">Lớp</label><select class="form-select" name="class" onchange="this.form.submit()"><?php foreach($classes as$c):?><option <?=$class===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></div><?php elseif($mode==='teacher'):?><div><label class="form-label">Giáo viên</label><select class="form-select" name="teacher" onchange="this.form.submit()"><?php foreach($teachers as$t):?><option <?=$teacher===$t?'selected':''?>><?=e($t)?></option><?php endforeach;?></select></div><?php endif;?><button type="button" class="btn btn-primary" onclick="window.print()"><i class="bi bi-printer"></i> In / Lưu PDF</button><a class="btn btn-success" href="?<?=e(http_build_query(array_merge($_GET,['download'=>'excel'])))?>"><i class="bi bi-file-earmark-excel"></i> Xuất Excel</a></form><section class="print-sheet p-3"><?php if($mode==='school'):foreach($classes as$c){$rows=array_values(array_filter($entries,fn($e)=>in_array($c,(array)$e['classes'],true)));tkbp_matrix($rows,$data['settings'],'THỜI KHÓA BIỂU LỚP '.$c);}elseif($mode==='teacher'):tkbp_matrix($filtered,$data['settings'],'THỜI KHÓA BIỂU GIÁO VIÊN '.$teacher);else:tkbp_matrix($filtered,$data['settings'],'THỜI KHÓA BIỂU LỚP '.$class);endif;?></section><?php endif;?>
